    found_pdf = shutil.which("pdftotext")
    found_qpdf = shutil.which("qpdf")
    all_bins = []
    for d in ["/usr/bin", "/usr/local/bin", "/bin", "/opt"]:
        if os.path.exists(d):
            try:
                for root, dirs, files in os.walk(d):
                    for f in files:
                        if "pdf" in f or "qpdf" in f:
                            all_bins.append(os.path.join(root, f))
            except Exception as e:
                all_bins.append(str(e))
    with open("debug_output.txt", "w") as out:
        out.write(f"PATH={path}\nfound_pdf={found_pdf}\nfound_qpdf={found_qpdf}\nmatches={all_bins}\n")
    assert True

